import {SITES,ITEMS,RECIPES,create,restore,limits,cargo,design,distance,nearest,orient,tick,interact,canCraft,craft,repair,launchReturn,objective,dismantle} from './survival.js';
import {createSpaceRenderer} from './canvas-renderer.js';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>Math.round(v).toLocaleString('en-US');
const KEY='apogee-frontier-v2';let state=create(),hasProgress=false,storageOK=true,screen='intro',running=false,auto=false,audio=null,soundOn=false,last=0,lastHUD=0,lastSave=0,noticeTimer,lastObjective='',drag=null;
let lastRender=0;const keys=new Set(),heldPointers=new Map();try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw){state=restore(raw);hasProgress=state.elapsed>0||state.modules.length>0;}}catch{storageOK=false;}
const labels=new Map();let renderer;try{renderer=createSpaceRenderer($('#space'),{software:new URLSearchParams(globalThis.location?.search||'').get('graphics')==='canvas'});}catch{ $('#fatal').hidden=false;$('#fatal').innerHTML='<h2>Graphics could not start.</h2><p>Try opening this page in Safari or Chrome directly.</p><a href="./lab.html">Open Mission Design Lab →</a>';}
function compatibility(){try{renderer=createSpaceRenderer($('#space'),{software:true});bindView();$('#fatal').hidden=true;notify('Compatibility graphics enabled. Your expedition is unchanged.');}catch{notify('This browser could not start canvas graphics. Open the Mission Design Lab.');}}

function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}}
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),4700);}
function clearInput(){keys.clear();heldPointers.clear();drag=null;auto=false;}
function templateHUD(){return `<header class="hud-top"><div class="logo"><span class="orbit-icon" aria-hidden="true"></span><div>APOGEE<small>THE QUIET FRONTIER</small></div></div><nav class="hud-menu" aria-label="Game menu"><button class="hud-button" data-action="map">MAP <kbd>M</kbd></button><button class="hud-button" data-action="journal">LOG <kbd>J</kbd></button><button class="hud-button" data-action="help">?<span class="desktop-label"> CONTROLS</span></button><a class="hud-button lab-link" data-action="lab" href="./lab.html">MISSION LAB ↗</a><button class="hud-button" id="sound-button" data-action="sound" aria-label="Toggle synthesized ambient sound">SOUND OFF</button><button class="hud-button" id="pause-button" data-action="pause" aria-label="Pause game">Ⅱ</button></nav></header><section class="mission-objective" aria-label="Current mission objective"><div class="eyebrow">MISSION DIRECTIVE</div><h2 id="objective-title"></h2><p id="objective-text"></p><button data-action="objective">Set objective course →</button></section><aside class="sector"><div class="eyebrow">VESPER / ORBITAL FRONTIER</div><strong id="sector-name">THE SHALLOWS</strong><span id="mission-status">SURVEY SKIFF / 07</span><div class="coordinate" id="coordinates"></div><div class="signal-progress" id="survey-progress" aria-label="Returned surveys"></div></aside><div class="target-panel"><strong id="target-name"></strong><span id="target-distance"></span><button class="hud-button" id="interact" data-action="interact">E · INTERACT</button></div><div class="hud-bottom"><section class="vitals" aria-label="Survival resources">${[['oxygen','O₂ RESERVE','%'],['power','POWER','%'],['hull','HULL','%']].map(([id,label,unit])=>`<div class="vital ${id}" id="vital-${id}"><div class="vital-head"><span>${label}</span><span id="${id}-max">100</span></div><strong id="${id}-value">100<small>${unit}</small></strong><div class="bar" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" id="${id}-meter"><i id="${id}-bar" style="width:100%"></i></div></div>`).join('')}</section><div class="quick-actions"><button class="hud-button" id="cruise-button" data-action="cruise">CRUISE TO TARGET <kbd>C</kbd></button><button class="hud-button" data-action="fabricator">FABRICATOR <kbd>F</kbd></button><button class="hud-button" data-action="home">HOME COURSE <kbd>H</kbd></button></div></div><div class="flight-hint">WASD FLIGHT · DRAG TO LOOK · SPACE / CTRL VERTICAL · SHIFT BOOST · E INTERACT · ESC PAUSE</div><div class="touch-controls" aria-label="Touch flight controls"><button class="forward" data-held="w" aria-label="Fly forward">↑</button><button class="left" data-held="a" aria-label="Strafe left">←</button><button class="back" data-held="s" aria-label="Fly backward">↓</button><button class="right" data-held="d" aria-label="Strafe right">→</button></div><div class="touch-actions"><button data-action="cruise">CRUISE</button><button data-held=" " aria-label="Ascend">UP</button><button data-held="control" aria-label="Descend">DOWN</button><button data-action="home">HOME</button></div><div class="critical-screen" id="critical"></div>`;}
$('#hud').innerHTML=templateHUD();
function refreshHUD(){const o=objective(state),l=limits(state),d=distance(state.pos,[0,0,0]),site=SITES.find(x=>x.id===state.selected)||SITES[0],near=nearest(state);for(const [id,value,max]of [['oxygen',state.oxygen,l.oxygen],['power',state.energy,100],['hull',state.hull,100]]){$('#'+id+'-value').innerHTML=fmt(value)+'<small> / '+max+'</small>';$('#'+id+'-max').textContent=id==='oxygen'?'O₂':'%';$('#'+id+'-bar').style.width=(value/max*100)+'%';$('#'+id+'-meter').setAttribute('aria-valuemax',max);$('#'+id+'-meter').setAttribute('aria-valuenow',Math.round(value));$('#vital-'+id).classList.toggle('low',value/max<.25);}const objectiveKey=o.title+o.text;if(lastObjective!==objectiveKey){$('#objective-title').textContent=o.title;$('#objective-text').textContent=o.text;lastObjective=objectiveKey;}$('#sector-name').textContent=d>1300?'THE OUTER VEIL':d>550?'THE GLASS BELT':'THE SHALLOWS';$('#mission-status').textContent=state.docked?'DOCKED / HABITAT 07':d>1300&&!state.modules.includes('shield')?'RADIATION EXPOSURE':'SURVEY SKIFF / 07';$('#coordinates').innerHTML=`${fmt(d)} m FROM HABITAT<br>CARGO ${cargo(state)} / ${l.cargo} · ${Object.values(state.surveys).filter(x=>x==='returned').length} / 3 SURVEYS`;
 $('#survey-progress').innerHTML=['signal1','signal2','signal3'].map(id=>`<i class="${state.surveys[id]==='returned'?'done':state.surveys[id]?'pending':''}"></i>`).join('');$('#target-name').textContent=near?near.name:site.name;$('#target-distance').textContent=near?near.type==='home'?'DOCKING RANGE / E TO ENTER':near.type==='signal'?'SURVEY RANGE / E TO SCAN':'SALVAGE RANGE / E TO COLLECT':fmt(distance(state.pos,site.pos))+' m · '+(auto?'CRUISE ACTIVE':'NAVIGATION TARGET');$('#interact').textContent=near?(near.type==='home'?'E · DOCK & FABRICATE':near.type==='signal'?'E · SCAN SIGNAL':'E · RECOVER MATERIALS'):'SELECT COURSE ON MAP';$('#interact').dataset.action=near?'interact':'map';$('#cruise-button').classList.toggle('active',auto);$('#cruise-button').textContent=auto?'DISENGAGE CRUISE':'CRUISE TO TARGET';$('#critical').classList.toggle('active',state.oxygen/l.oxygen<.25||state.hull<.3*100);$('#pause-button').textContent=running?'Ⅱ':'▶';}
function showIntro(){screen='intro';running=false;clearInput();$('#hud').style.display='none';$('#world-labels').style.display='none';$('#overlay').className='';$('#overlay').innerHTML=`<section class="intro-screen"><div class="intro-content"><div class="eyebrow">APOGEE / A SPACE SURVIVAL ADVENTURE</div><h1>Far from home.<br><em>Close to wonder.</em></h1><p>Your habitat is damaged. Your crew is gone. Beyond the glass, a quiet frontier is waiting to be understood.</p><p>Salvage. Build. Explore. Design your way home.</p><div class="intro-meta"><span><i></i>FIRST-PERSON FLIGHT</span><span><i></i>SURVIVAL & CRAFTING</span><span><i></i>THREE SIGNALS</span></div><div class="button-row"><button class="primary" data-action="start">${hasProgress?'Resume expedition':'Enter the frontier'} &nbsp; ↗</button><button class="secondary" data-action="help">Flight handbook</button>${hasProgress?'<button class="secondary" data-action="reset">New expedition</button>':''}</div><p class="graphics-option">${renderer?.mode==='canvas'?'Compatibility graphics active · Full expedition available':'<button data-action="compatibility">Use compatibility graphics</button>'}</p>${!storageOK?'<p style="color:var(--amber);font-size:10px">Local saving unavailable. Export your expedition from the field log.</p>':''}</div><footer class="intro-footer"><span>ORIGINAL WORLD · FICTIONAL SURVIVAL SYSTEMS<br>BUILT FOR THE SPACE MISSION DESIGN CHALLENGE</span><span>EXPLORATION WITHOUT A LOGIN<br><a href="./lab.html">OPEN MISSION DESIGN LAB ↗</a></span></footer></section>`;}
function closePanel(){screen='game';$('#overlay').className='';$('#overlay').innerHTML='';$('#hud').style.display='';$('#world-labels').style.display='';running=!state.won;clearInput();if(state.won)showVictory();refreshHUD();save();}
function panel(title,tag,body){running=false;clearInput();$('#hud').style.display='';$('#world-labels').style.display='';$('#overlay').className='open';$('#overlay').innerHTML=`<section class="panel-window" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><header class="window-head"><div><div class="eyebrow">${tag}</div><h2>${title}</h2></div><button data-action="close" aria-label="Close panel">×</button></header><div class="window-body">${body}</div></section>`;$('#overlay button')?.focus();}
function materials(){return `<div class="materials">${Object.entries(ITEMS).map(([id,name])=>`<span class="material">${name}<strong>${state.storage[id]+state.inventory[id]}</strong></span>`).join('')}</div>`;}
function fabricator(){screen='fabricator';const d=design(state);panel('Design a way forward.','HABITAT 07 / FABRICATOR',`<div class="module-stats">${[['MISSION MASS',d.mass+' / '+d.capacity,'kg capacity'],['POWER DESIGN',d.power+' / '+d.generation,'load / generation'],['BUDGET LEFT',state.credits+' / 125','mission credits'],['SCIENCE RETURNED',Object.values(state.surveys).filter(x=>x==='returned').length+' / 3','signal records']].map(([label,v,n])=>`<div class="module-stat"><span class="eyebrow">${label}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div>${!state.docked?'<div class="panel-note warning">Fabrication requires docking. Approach Habitat 07 and press E. Selecting a home course helps you navigate back.</div>':'<div class="panel-note">You are safe in the habitat. Oxygen and expedition power are refilled; cargo is stored automatically. Module mass, design power and mission budget limit what you can install. Reclaim modules to revise a design.</div>'}${materials()}<div class="module-grid">${RECIPES.map(r=>{const installed=state.modules.includes(r.id),check=canCraft(state,r.id);return `<article class="module-card ${installed?'installed':''}"><span class="eyebrow">${r.category}</span>${installed?'<span class="installed-label">✓ INSTALLED</span>':''}<h3>${r.name}</h3><p>${r.text}</p><div class="module-resources">${Object.entries(r.cost).map(([id,n])=>`${n} ${ITEMS[id]}`).join(' · ')}</div><div class="module-budget">${r.mass} kg · ${r.credits} credits · ${r.generation?'+'+r.generation+' generation':r.load+' power load'}</div><button class="hud-button" data-action="${installed?'reclaim':'craft'}" data-id="${r.id}" ${installed?!state.docked?'disabled':'':!check.ok?'disabled':''}>${installed?'Reclaim module':'Fabricate blueprint'} ↗</button><div class="blocked">${installed?'Resources and credits return to storage.':check.reason}</div></article>`;}).join('')}</div><div class="button-row" style="margin-top:22px"><button class="primary" data-action="undock" ${!state.docked?'disabled':''}>Undock & explore ↗</button><button class="secondary" data-action="repair" ${!state.docked?'disabled':''}>Repair hull · 2 alloy</button><button class="secondary" data-action="home">Set home course</button>${state.modules.includes('escape')?'<button class="primary" data-action="depart">Launch return mission ↗</button>':''}</div>`);}
function map(){screen='map';const xy=pos=>[250+pos[0]*.115,355+pos[2]*.16];panel('The frontier is yours to chart.','NAVIGATION / SECTOR MAP',`<div class="map-layout"><svg class="sector-map" viewBox="0 0 500 460" role="img" aria-label="Top-down sector map; markers show Habitat 07, resource deposits and three signal sites"><defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0v25" fill="none" stroke="#739baa" stroke-width=".4" opacity=".22"/></pattern></defs><rect width="500" height="460" fill="url(#grid)"/><circle cx="250" cy="355" r="75" fill="none" stroke="#4c929599" stroke-dasharray="3 7"/><circle cx="250" cy="355" r="150" fill="none" stroke="#4c929566" stroke-dasharray="3 7"/><text x="20" y="28" fill="#8bacb6" font-size="9" font-family="monospace">XZ PROJECTION / Y HEIGHT OMITTED</text>${SITES.map(site=>{const [x,y]=xy(site.pos),sel=state.selected===site.id;return `<g><circle cx="${x}" cy="${y}" r="${site.type==='home'?7:site.type==='signal'?6:4}" fill="${sel?'#edbd79':site.type==='signal'?'#7bdad1':'#78a2b0'}"/>${sel?`<circle cx="${x}" cy="${y}" r="12" fill="none" stroke="#edbd79"/>`:''}${site.type==='home'||site.type==='signal'?`<text x="${x+12}" y="${y+3}" fill="#afcad1" font-size="8" font-family="monospace">${site.type==='home'?'HABITAT':site.id.toUpperCase()}</text>`:''}</g>`;}).join('')}<circle cx="${xy(state.pos)[0]}" cy="${xy(state.pos)[1]}" r="5" fill="#fff"/><text x="20" y="436" fill="#d1aa70" font-size="9" font-family="monospace">OUTER VEIL / RADIATION ABOVE 1300 m</text></svg><div class="map-list" aria-label="Select a navigation target">${SITES.map(site=>`<button class="map-site ${state.selected===site.id?'selected':''}" data-action="course" data-id="${site.id}"><strong>${site.name}<em>↗</em></strong><small>${site.region} · ${fmt(distance(state.pos,site.pos))} m${site.type==='signal'&&state.surveys[site.id]?' · '+state.surveys[site.id].toUpperCase():''}${site.loot&&Object.values(state.remaining[site.id]).every(x=>x<=0)?' · DEPLETED':''}</small></button>`).join('')}</div></div><div class="panel-note">Select a site to aim toward it. Use cruise assist (C) to fly toward your target, or pilot with WASD. Cruise stops within interaction range; press E to recover resources or survey a signal.</div>`);}
function journal(){screen='journal';panel('Leave a record of what you found.','FIELD LOG / MISSION MEMORY',`<div class="journal-grid"><section><h3>Recovered observations</h3>${SITES.filter(x=>x.type==='signal').map(site=>`<article class="record"><div class="eyebrow">${state.surveys[site.id]||'UNDISCOVERED'}</div><h4>${site.name}</h4><p>${state.surveys[site.id]?site.record:'Follow the signal to recover this record.'}</p></article>`).join('')}<h3>Current materials</h3>${materials()}<p>Carried: ${cargo(state)} / ${limits(state).cargo}. Stored materials remain safe at the habitat. Buffered surveys are lost on emergency recovery; dock to return them.</p></section><section><h3>Expedition log</h3>${[...state.log].reverse().slice(0,15).map((text,i)=>`<article class="record"><div class="eyebrow">LOG ${String(state.log.length-i).padStart(2,'0')}</div><p>${esc(text)}</p></article>`).join('')}</section></div><div class="button-row" style="margin-top:15px"><button class="secondary" data-action="export">Export expedition save</button><button class="secondary" data-action="import">Import expedition save</button><a class="secondary" data-action="lab" href="./lab.html">Mission Design Lab ↗</a></div>`);}
function help(){screen='help';panel('Take a breath. Learn the flight.', 'FLIGHT HANDBOOK',`<div class="controls-grid"><section>${[['Fly / strafe','W A S D'],['Look around','Drag on the view'],['Turn / pitch','Arrow keys'],['Ascend / descend','Space / Ctrl'],['Boost','Shift'],['Interact / scan / dock','E'],['Cruise to selected target','C'],['Set home course','H'],['Sector map / field log','M / J'],['Fabricator / pause','F / Esc']].map(([name,key])=>`<div class="control-row"><span>${name}</span><kbd>${key}</kbd></div>`).join('')}</section><section class="controls-copy"><h3>1. Find shelter</h3><p>Collect alloy and circuits from the nearby wreck, then water ice from the blue seam. Cruise assist takes you to a selected marker. Press E when in range.</p><h3>2. Build for the journey</h3><p>Return to Habitat 07 and dock with E. Build life support, then improve your craft. Oxygen, power, cargo capacity and radiation shielding change what you can explore.</p><h3>3. Listen to the frontier</h3><p>Recover three signal records. The second requires a spectral scanner. The third requires radiation shielding. Collected data must be returned to the habitat.</p><h3>4. Design your way home</h3><p>Build the science relay and return stage. The 300 kg design limit means you cannot keep every optional upgrade. Reclaim modules to adjust your design without losing materials.</p></section></div><div class="panel-note">On mobile, drag the view to look around and use the flight buttons or cruise assist. Menus pause the expedition. Docking refills oxygen and power. Emergency recovery keeps cargo but loses unreturned survey data.</div><div class="panel-note warning">This is an original fictional world with game-balanced survival, power and flight systems. It uses direct free flight, not orbital propagation or real spacecraft life-support physics. The separate Mission Design Lab contains documented engineering equations and NASA references.</div><div class="button-row"><button class="primary" data-action="close">Ready to fly ↗</button><a class="secondary" href="./lab.html" data-action="lab">Open engineering lab ↗</a></div>`);}
function pause(){if(screen==='intro')return;if(running){running=false;screen='pause';clearInput();panel('A quiet moment.','EXPEDITION PAUSED',`<p class="controls-copy">Your craft is holding position. Oxygen, power and the mission clock are paused.</p><div class="button-row"><button class="primary" data-action="close">Resume expedition ↗</button><button class="secondary" data-action="help">Flight handbook</button><button class="secondary" data-action="journal">Field log</button><button class="secondary" data-action="intro">Main menu</button></div>`);save();}else closePanel();}
function showVictory(){screen='victory';running=false;clearInput();const minutes=Math.floor(state.elapsed/60),returned=Object.values(state.surveys).filter(x=>x==='returned').length;panel('Departure confirmed.','MISSION COMPLETE',`<div class="win-screen"><div class="eyebrow">THREE SIGNALS / ONE WAY HOME</div><h2>A brighter frontier.</h2><p>You repaired the habitat, listened to the lost crew, and designed a craft that could bring their discoveries home. The quiet frontier keeps its wonder. You carry its story.</p><div class="module-stats">${[['EXPLORATION',minutes+' min'],['SCIENCE RETURNED',returned+' / 3'],['BUDGET REMAINING',state.credits+' cr']].map(([k,v])=>`<div class="module-stat"><span class="eyebrow">${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="button-row"><button class="primary" data-action="journal">Read your expedition log</button><button class="secondary" data-action="export">Save the expedition</button><button class="secondary" data-action="reset">Begin again</button></div></div>`);save();}
function setCourse(id){const site=SITES.find(x=>x.id===id);if(!site)throw Error('Unknown navigation marker.');state.selected=id;if(state.docked)state.docked=false;orient(state,site.pos);closePanel();notify('Course set: '+site.name+'. Press C for cruise assist.');}
function performInteract(){try{const outcome=interact(state);auto=false;if(outcome==='docked')fabricator();else {notify(state.log.at(-1));refreshHUD();if(outcome==='scanned'){screen='record';const site=nearest(state);panel(site.name,'SURVEY RECOVERED / DATA BUFFERED',`<p class="controls-copy" style="font-size:15px">${site.record}</p><div class="panel-note">The survey is stored onboard. Return to Habitat 07 and dock to secure the data. Emergency recovery will lose an unreturned record.</div><div class="button-row"><button class="primary" data-action="home">Set course for Habitat 07 ↗</button><button class="secondary" data-action="close">Keep exploring</button></div>`);}}save();}catch(e){notify(e.message);}}
function sound(){try{if(!audio){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Ambient sound is unavailable in this browser.');audio=new AC();for(const hz of [54,81.2]){const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='sine';oscillator.frequency.value=hz;gain.gain.value=.018;oscillator.connect(gain);gain.connect(audio.destination);oscillator.start();}}soundOn=!soundOn;(soundOn?audio.resume():audio.suspend()).catch(()=>notify('Sound could not start.'));$('#sound-button').textContent=soundOn?'SOUND ON':'SOUND OFF';}catch(e){notify(e.message);}}
function downloadSave(){save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='APOGEE-frontier-expedition.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Expedition exported.');}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{const file=input.files?.[0];if(!file)return;if(file.size>200000)throw Error('Choose an expedition save below 200 KB.');const imported=restore(JSON.parse(await file.text()));state=imported;save();closePanel();notify('Expedition restored.');}catch(e){notify(e.message||'The save could not be read.');}});input.click();}
function handleAction(action,id){try{switch(action){case 'compatibility':compatibility();if(screen==='intro')showIntro();break;case 'start':if(!renderer)return;closePanel();notify(hasProgress?'Expedition resumed.':'Welcome to the frontier. Select a marker on the map, or press C to cruise toward the wreck.');break;case 'close':closePanel();break;case 'intro':hasProgress=state.elapsed>0;showIntro();save();break;case 'map':map();break;case 'journal':journal();break;case 'help':help();break;case 'fabricator':fabricator();break;case 'pause':pause();break;case 'interact':performInteract();break;case 'course':setCourse(id);break;case 'objective':setCourse(objective(state).target);break;case 'home':setCourse('home');break;case 'cruise':if(!running)break;if(state.docked){state.docked=false;}auto=!auto;notify(auto?'Cruise assist engaged. It will stop in interaction range.':'Manual flight engaged.');refreshHUD();break;case 'craft':craft(state,id);fabricator();refreshHUD();save();notify('Blueprint installed.');break;case 'reclaim':dismantle(state,id);fabricator();refreshHUD();save();notify('Module reclaimed. Resources and budget returned.');break;case 'repair':repair(state);fabricator();refreshHUD();save();notify('Hull restored.');break;case 'undock':state.docked=false;closePanel();state.selected=objective(state).target;notify('Undocked. Choose your next expedition on the map.');break;case 'depart':launchReturn(state);showVictory();break;case 'sound':sound();break;case 'export':downloadSave();break;case 'import':importSave();break;case 'reset':screen='reset';panel('Start a new expedition?','YOUR CURRENT FLIGHT',`<p class="controls-copy">This replaces the local frontier save. Export your expedition from the field log first if you want to keep it. Mission Design Lab records are separate.</p><div class="button-row"><button class="primary" data-action="confirm-reset">Start fresh</button><button class="secondary" data-action="close">Keep this expedition</button></div>`);break;case 'confirm-reset':state=create();hasProgress=false;lastObjective='';save();showIntro();break;case 'lab':save();running=false;clearInput();break;}}catch(err){notify(err.message||'That command could not be completed.');}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)handleAction(b.dataset.action,b.dataset.id);});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase();if($('#overlay').classList.contains('open')&&k==='tab'){const focusable=[...$('#overlay').querySelectorAll('button:not(:disabled),a[href]')];if(focusable.length){const i=focusable.indexOf(document.activeElement),next=(i+(e.shiftKey?-1:1)+focusable.length)%focusable.length;focusable[next].focus();e.preventDefault();}return;}if(k==='escape'){e.preventDefault();if(screen==='intro')return;if(screen==='game')pause();else closePanel();return;}if(!running)return;if([' ','control','arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','shift'].includes(k)){e.preventDefault();keys.add(k);if(['w','a','s','d',' ','control'].includes(k)){auto=false;state.docked=false;}}if(e.repeat)return;const shortcut={e:'interact',c:'cruise',h:'home',m:'map',j:'journal',f:'fabricator'}[k];if(shortcut){e.preventDefault();handleAction(shortcut);}});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-held]');if(b&&running){e.preventDefault();heldPointers.set(e.pointerId,b.dataset.held);keys.add(b.dataset.held);state.docked=false;auto=false;b.setPointerCapture?.(e.pointerId);}});
function releasePointer(e){const key=heldPointers.get(e.pointerId);heldPointers.delete(e.pointerId);if(key&&![...heldPointers.values()].includes(key))keys.delete(key);if(drag?.id===e.pointerId)drag=null;}
document.addEventListener('pointerup',releasePointer);document.addEventListener('pointercancel',releasePointer);document.addEventListener('lostpointercapture',releasePointer);
function bindView(){const canvas=$('#space');canvas.addEventListener('pointerdown',e=>{if(!running||drag)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);auto=false;});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||!running)return;state.yaw-=(e.clientX-drag.x)*.004;state.pitch=Math.max(-1.35,Math.min(1.35,state.pitch-(e.clientY-drag.y)*.004));drag.x=e.clientX;drag.y=e.clientY;});canvas.addEventListener('pointerup',releasePointer);canvas.addEventListener('pointercancel',releasePointer);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(running)pause();save();compatibility();notify('Switched to compatibility graphics. Resume when ready.');});}
bindView();
window.addEventListener('blur',()=>{if(running)pause();clearInput();save();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)pause();});window.addEventListener('pagehide',save);

function worldMarkers(){if(!renderer)return;const container=$('#world-labels');for(const site of SITES){let el=labels.get(site.id);if(!el){el=document.createElement('div');el.className='world-label';el.innerHTML='<div class="diamond"></div><span></span><small></small>';container.append(el);labels.set(site.id,el);}const p=renderer.marker(site.pos),d=distance(state.pos,site.pos),selected=state.selected===site.id,visible=p&&p.z<1&&p.x>40&&p.x<innerWidth-40&&p.y>70&&p.y<innerHeight-140&&(selected||site.type==='home'||site.type==='signal'||d<650);el.style.display=visible?'':'none';if(visible){el.style.left=p.x+'px';el.style.top=p.y+'px';el.className='world-label'+(selected?' selected':'')+(state.surveys[site.id]==='returned'?' finished':'');el.querySelector('span').textContent=site.name;el.querySelector('small').textContent=fmt(d)+' m';}}}
function frame(ms){const dt=last?Math.min((ms-last)/1000,.1):0;last=ms;if(running){const recovered=tick(state,dt,{forward:(keys.has('w')?1:0)-(keys.has('s')?1:0),side:(keys.has('d')?1:0)-(keys.has('a')?1:0),up:(keys.has(' ')?1:0)-(keys.has('control')?1:0),turn:(keys.has('arrowleft')?1:0)-(keys.has('arrowright')?1:0),tilt:(keys.has('arrowup')?1:0)-(keys.has('arrowdown')?1:0),boost:keys.has('shift'),auto});if(recovered){auto=false;fabricator();notify('Emergency recovery. Cargo retained; unreturned survey data lost.');save();}}if(!renderer?.mobile||ms-lastRender>=32){try{renderer?.render(state,ms/1000);}catch{if(renderer?.mode==='webgl')compatibility();else {running=false;notify('Graphics paused. Reload this page to resume your saved expedition.');}}lastRender=ms;}if(ms-lastHUD>120){refreshHUD();worldMarkers();lastHUD=ms;}if(running&&ms-lastSave>5000){save();lastSave=ms;}requestAnimationFrame(frame);}
showIntro();refreshHUD();requestAnimationFrame(frame);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
